const initialV4Stacks=()=>Object.fromEntries(KEYS.map(k=>[k,[]]));let v4Stacks=initialV4Stacks(),v4Filter='全部',calDevice='iPhone',calMode='busy',selectedCalendars=['个人','学习与项目'],calRequest=false,calDefault='学习与项目',calChoices=['个人','学习与项目','家庭'],calSimulated=false,localStatus=null,stateDraft=null,recordForm={skill:'原型设计',note:'',minutes:'25',date:'2026-11-05',time:'09:30'},addedRecords=[],activeRecord=null,planEdit={name:'原型设计',start:'09:30',end:'10:15'},flowError='',focusedFrom=null;
