skillsV4.forEach(s=>s.originalName=s.name);const notifyPrefs={plan:false,review:false};function currentSkillName(name){return skillsV4.find(s=>s.originalName===name||s.name===name)?.name||name}function recs(name){return [...addedRecords,...(scenario==='first'||scenario==='error'?[]:scenario==='short'?[{...seedRecords[0],minutes:20}]:seedRecords)].map(r=>({...r,skill:currentSkillName(r.skill)})).filter(r=>!name||r.skill===currentSkillName(name))}function applyRenamesV4(root){const pairs=skillsV4.filter(s=>s.originalName&&s.originalName!==s.name);if(!pairs.length)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);while(walker.nextNode()){const n=walker.currentNode;if(n.parentElement?.closest('script,style,textarea'))continue;let t=n.nodeValue;for(const s of pairs)t=t.replaceAll(s.originalName,s.name);n.nodeValue=t}}
const V4=(title,a,cls='')=>`<button data-v4="${a}" class="${cls}">${title}</button>`;
const vPrimary=(title,a)=>V4(title,a,'primary');const vMetrics=items=>`<dl>${items.map(([k,v])=>`<div class="metric-row"><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl>`;
const obj=(ic,title,desc,metrics='')=>`<section class="object-panel glass"><div class="object-icon">${icon(ic)}</div><h3>${esc(title)}</h3><p>${esc(desc)}</p>${metrics?`<div class="object-meta">${metrics.map(([n,l])=>`<div><strong>${n}</strong><span>${l}</span></div>`).join('')}</div>`:''}</section>`;
const vRow=(ic,title,sub,right,a)=>`<button class="compact-row" data-v4="${a}"><span class="row-icon">${icon(ic)}</span><div><strong>${title}</strong>${sub?`<p>${sub}</p>`:''}</div>${right?`<span>${right}</span>`:''}${icon('chevron')}</button>`;
const toggle=(title,sub,on,a)=>`<button class="toggle-row" data-v4="${a}"><div><strong>${title}</strong><p>${sub}</p></div><span class="toggle ${on?'on':''}"><i></i></span></button>`;
function recordCard(r){return `<button class="record-card glass" data-v4="record:${r.id}"><time>${r.date.replaceAll('-','.')} · ${r.time}</time><strong>${r.skill}</strong><p>${esc(r.note)}</p><div class="record-bottom"><span>${r.minutes} 分钟 · 手动记录</span><span>查看记录 ↗</span></div></button>`}
function navigateV4(key,route,replace=false,fromPop=false){if(!KEYS.includes(key))return;if(route.startsWith('capture:')){const s=skillsV4.find(s=>s.id===route.split(':')[1]);if(s)recordForm.skill=s.name}if(!replace)v4Stacks[key].push(route);else v4Stacks[key]=route?[route]:[];paintV4(key);if(!fromPop){const single=document.body.classList.contains('single');const next=single?'?screen='+key+(route?'&view='+encodeURIComponent(route):''):location.search;history.pushState({v4Stacks:JSON.parse(JSON.stringify(v4Stacks))},'',next)}}
function backV4(key){v4Stacks[key].pop();paintV4(key);const route=v4Stacks[key].at(-1);history.replaceState({v4Stacks:JSON.parse(JSON.stringify(v4Stacks))},'',document.body.classList.contains('single')?'?screen='+key+(route?'&view='+encodeURIComponent(route):''):location.search)}
function paintV4(key){const phone=document.getElementById(key);phone.querySelector('.subpage')?.remove();const route=v4Stacks[key].at(-1);if(!route)return;const view=routeV4(key,route);const node=document.createElement('section');node.className='subpage'+(view.footer?' has-footer':'');node.dataset.route=route;node.setAttribute('aria-label',view.title);node.innerHTML=`${status()}<header class="child-toolbar"><button class="glass back" data-v4="back" aria-label="返回">${icon('chevron')}</button><strong>${view.title}</strong>${view.action||'<span></span>'}</header><div class="child-body">${view.body}</div>${view.footer?`<div class="child-footer">${view.footer}</div>`:''}`;phone.append(node);applyRenamesV4(node);node.querySelector('.back')?.focus({preventScroll:true});if(view.bind)view.bind(node)}
function libraryV4(){const available=scenario==='first'?[]:skillsV4;let list=available.filter(s=>v4Filter==='全部'||s.category===v4Filter);return {title:'技能库',action:V4(icon('plus'),'skill-new','glass'),body:`<label class="child-search glass">${icon('search')}<input id="library-search" placeholder="查找技能、关联目标" aria-label="查找技能"></label><div class="chips">${['全部','设计与表达','研究与理解','日常与健康'].map(c=>V4(c,'filter:'+c,v4Filter===c?'selected':'')).join('')}</div>${available.length?`<button class="skill-spotlight glass" data-v4="skill:prototype"><div class="object-icon">${icon('cube')}</div><div><strong>原型设计</strong><p>完成作品集项目 · 问题与方案</p><p>${recs('原型设计').length} 次实际执行 · ${recs('原型设计').reduce((s,r)=>s+r.minutes,0)} 分钟</p></div>${icon('chevron')}</button><div class="library-group"><span>全部技能</span><small>${list.length} 个 · 按实际关联组织</small></div><div class="skill-tiles">${list.map(s=>`<button class="skill-tile glass" data-v4="skill:${s.id}" data-search="${s.name+s.target}">${icon(s.ic)}<strong>${esc(s.name)}</strong><p>${esc(s.target)}</p><small>${recs(s.name).length?recs(s.name).length+' 次执行':'尚无执行记录'}</small></button>`).join('')}</div><div class="child-list glass" style="margin-top:16px">${vRow('link','关联已有技能','加入目标中的一个模块','选择目标','link:prototype')}</div><p class="notice">记录呈现做过什么。掌握程度需要独立的证据。</p>`:empty('从一个技能开始','技能可以关联到目标和模块；每次执行都保留实际发生的内容。','folder','skill-new','创建技能')}`,bind:n=>n.querySelector('#library-search').addEventListener('input',e=>n.querySelectorAll('[data-search]').forEach(t=>t.hidden=!t.dataset.search.includes(e.target.value)))} }
function skillV4(id){const s=skillsV4.find(x=>x.id===id)||skillsV4[0],records=recs(s.name);return{title:'技能',action:V4(icon('edit'),'skill-edit:'+s.id,'glass'),body:`<div class="pathline">${s.target}${icon('chevron')}${s.module}</div>${obj(s.ic,s.name,s.definition,[[records.length,'次执行'],[records.reduce((n,r)=>n+r.minutes,0)+' 分钟','实际累计'],['未建立','掌握程度']])}<div class="child-list glass">${vRow('target','关联目标',s.target,s.module,'link:'+id)}${vRow('calendar','相关计划',id==='prototype'?'今天 09:30–10:15':id==='reading'?(readingMoved?'今天 14:30–15:00':'今天 14:00–14:30'):id==='walk'?'今天 17:30–18:00':'尚未安排','查看','skill-plan:'+id)}</div><div class="split-title">最近执行<span>${records.length} 条实际记录</span></div>${records.length?records.map(recordCard).join(''):`<div class="definition glass"><p>尚未记录执行。排入计划或打开此页都不会增加次数。</p></div>`}`,footer:vPrimary('记录一次执行','capture:'+id)}}
function goalV4(){return{title:'目标详情',action:V4(icon('edit'),'goal-edit','glass'),body:`${obj('target','完成作品集项目','把一个问题，做成可讲清楚的方案。',[[2,'个模块'],[4,'个技能'],[recs().filter(r=>skillsV4.find(s=>s.name===r.skill)?.target==='完成作品集项目').length,'次实际执行']])}<section class="definition glass"><div class="split-title no-margin"><span>完成依据</span><span>待确认</span></div>${vMetrics([['形成可讲解的项目方案','待确认'],['完成反馈走查并记录修改','待确认']])}</section><div class="child-list glass">${vRow('nodes','问题与方案','用户访谈 / 原型设计','2 个技能','module:discovery')}${vRow('doc','表达与验证','方案表达 / 可用性走查','2 个技能','module:delivery')}</div><div class="child-list glass">${vRow('folder','从技能库关联','选择现有技能，不重复创建','','link:prototype')}${vRow('doc','相关执行记录','保留关联与实际内容',recs().length+' 条','records')}</div><p class="notice">完成依据独立确认，不从时长或执行次数推算完成比例。</p>`,footer:vPrimary('关联技能','link:prototype')}}
function moduleV4(id){const ss=skillsV4.filter(s=>s.module===(id==='discovery'?'问题与方案':'表达与验证'));return{title:'模块',body:`<div class="pathline">完成作品集项目 ${icon('chevron')} ${id==='discovery'?'问题与方案':'表达与验证'}</div>${obj(id==='discovery'?'nodes':'doc',id==='discovery'?'问题与方案':'表达与验证',id==='discovery'?'通过研究理解问题，再用原型探索可能的方案。':'讲清楚方案，并通过实际走查保留反馈。',[[ss.length,'个关联技能'],[ss.reduce((n,s)=>n+recs(s.name).length,0),'次实际执行']])}<div class="child-list glass">${ss.map(s=>vRow(s.ic,s.name,s.definition,recs(s.name).length+' 次','skill:'+s.id)).join('')}</div><p class="notice">技能可以复用到多个模块；执行记录保留原关联。</p>`,footer:vPrimary('关联已有技能','link:prototype')}}
