function calendarV4(){return{title:'原生日历',body:`<div class="segment device-segment">${['iPhone','Mac'].map(d=>V4(d,'device:'+d,d===calDevice?'active':'')).join('')}</div><div class="device-picture"><svg width="39" height="70" viewBox="0 0 39 70"><rect x="2" y="1" width="35" height="68" rx="8" fill="#f8fcff85"/><path d="M14 5h11M14 64h11"/></svg><span class="device-link"></span><svg width="90" height="65" viewBox="0 0 90 65"><rect x="7" y="1" width="76" height="49" rx="4" fill="#f8fcff85"/><path d="M1 56h88l-6 5H7z"/></svg></div><section class="permission glass"><div class="permission-title">${icon('calendar')}<span>${calDevice} 日历</span></div><div class="status-line"><span>系统授权</span><strong>${calRequest?'等待系统结果':'尚未请求'}</strong></div><div class="status-line"><span>读取 / 写回</span><strong>${calSimulated?'隔离日历示例':'未连接'}</strong></div><p>在相应设备的原生 App 内授权。每台设备分别确认，不以另一台设备的状态代替。</p></section><h4>希望怎样使用日历？</h4>${['busy','write'].map(m=>`<button class="choice-tile glass" data-v4="cal-mode:${m}"><span class="checkcircle ${calMode===m?'checked':''}">${calMode===m?icon('check'):''}</span><div><strong>${m==='busy'?'查看占用并规划时间':'只添加计划'}</strong><p>${m==='busy'?'读取已有事件，需要系统完整访问权限':'保留已有事件私密性；无法据此检查占用'}</p></div></button>`).join('')}<div class="child-list glass">${vRow('folder','日历范围','选择纳入占用判断的日历',selectedCalendars.length+' 个示例','calendar-list')}${vRow('calendar','默认写入日历',calDefault,'示例','calendar-default')}${vRow('cloud','设备与同步','权限、写回与设备同步分别显示','','calendar-sync')}</div><p class="notice">已在设备配置的日历账户可由系统提供；跨设备同步取决于账户与系统设置。</p>`,footer:vPrimary(calRequest?'查看授权步骤':'继续授权流程','cal-request')}}
