function smartV4(){return{title:'智能调配',body:`<section class="smart-summary glass"><div class="object-icon">${icon('spark')}</div><div><strong>${readingMoved?'调整已应用':'1 项可审阅的调整'}</strong><p>11 月 5 日 · 3 项计划 · 105 分钟</p></div></section><section class="definition glass"><div class="split-title no-margin"><span>调整边界</span><span>保留固定事项</span></div>${vMetrics([['原型设计','09:30–10:15 · 保持'],['散步','17:30–18:00 · 保持'],['阅读与笔记','可移动，保持 30 分钟']])}</section><button class="proposal-card glass" style="width:100%;text-align:left" data-v4="smart-review"><div class="proposal-title"><span>阅读与笔记</span><small>${readingMoved?'已后移 30 分钟':'后移 30 分钟'}</small></div><div class="before-after"><div><small>原安排</small><strong>14:00</strong><p>至 14:30</p></div>${icon('chevron')}<div><small>建议安排</small><strong>14:30</strong><p>至 15:00</p></div></div><p style="font-size:10px;margin-top:13px">${calSimulated?'避开隔离日历示例中的 14:00 会议。':'依据示例偏好：14:30 后阅读，保持 30 分钟。'}</p></button><button class="integration-banner glass" data-v4="calendar"><span>${icon('calendar')}</span><span>原生日历${calSimulated?' · 已载入隔离示例':' · 未读取外部占用'}</span>${icon('chevron')}</button><div class="child-list glass">${vRow('filter','调配偏好','阅读 14:30 后 / 保留固定事项','','smart-preferences')}</div><div class="reason-list"><p>${icon('check')}只调整可移动的计划</p><p>${icon('clock')}保留原时长，实际执行独立记录</p><p>${icon('shield')}不自动改动外部日历中的事件</p></div><p class="notice">这是一项可检查的设计示例建议；没有调用实时智能调度服务。</p>`,footer:vPrimary(readingMoved?'查看与撤销':'审阅差异',readingMoved?'smart-result':'smart-review')}}
function smartReview(){return{title:'审阅调整',body:`<section class="proposal-card glass"><div class="proposal-title"><span>阅读与笔记</span><small>同日移动 · 30 分钟</small></div><div class="before-after"><div><small>当前</small><strong>14:00–14:30</strong><p>原计划</p></div>${icon('chevron')}<div><small>建议</small><strong>14:30–15:00</strong><p>保留时长</p></div></div></section><h4>为什么这样调整</h4><section class="definition glass"><p>${calSimulated?'14:00–14:30 与隔离日历示例中的会议重叠，移动阅读以避开固定事项。':'按本轮示例偏好，将阅读安排在 14:30 之后。'}原型设计与散步保持原时间，阅读时长仍为 30 分钟。</p></section><h4>影响检查</h4><section class="child-list glass">${vMetrics([['与已知计划重叠','无'],['与散步间隔','3 小时 → 2 小时 30 分'],['计划总量','105 分钟 → 105 分钟'],['外部日历占用',calSimulated?'隔离示例：14:00–14:30 会议':'尚未读取，无法确认'],['设备日历写入','不写入，仅修改本页计划']])}</section>${calSimulated?'<p class="notice">示例会议为固定事项，调配只移动 QuestLife 阅读计划。</p>':'<p class="notice">连接原生日历后才能同时检查外部占用。你仍可先保留或调整自己的 QuestLife 计划。</p>'}${flowError?`<p class="error-inline">${flowError}</p>`:''}`,footer:V4('保留原安排','back','sub-secondary')+vPrimary('确认应用','smart-apply')}}
function routeV4(key,route){const [base,id]=route.split(':');if(['first','error'].includes(scenario)&&['skill','goal','module','plan','smart','smart-review','smart-result','record'].includes(base)){return{title:scenario==='error'?'暂时无法读取':'当前还没有内容',body:empty(scenario==='error'?'读取尚未恢复':'从一次实际记录开始',scenario==='error'?'当前请求未取得结果，重试后再继续。':'先创建目标或记录实际发生的内容；不会显示其他情境的历史。','doc','retry',scenario==='error'?'重试示例':'查看成熟示例')}}switch(base){
case 'library':return libraryV4();case 'skill':return skillV4(id);case 'goal':return goalV4();case 'module':return moduleV4(id);case 'capture':return captureV4(id);case 'capture-review':return captureReview();case 'records':return recordsV4(id);case 'record':{const r=recs().find(r=>r.id===id)||seedRecords[0];return{title:'执行记录',body:`${obj(skillsV4.find(s=>s.name===r.skill)?.ic||'doc',r.skill,r.date.replaceAll('-','.')+' · '+r.time)}<section class="definition glass"><p class="record-detail-note">${esc(r.note)}</p></section><section class="child-list glass">${vMetrics([['实际时长',r.minutes+' 分钟'],['来源','手动记录'],['关联技能',r.skill],['关联目标',skillsV4.find(s=>s.name===r.skill)?.target||'待关联']])}</section><p class="notice">这条记录说明实际执行，不代表目标已完成或技能已掌握。</p>`,footer:vPrimary('查看关联技能','skill:'+skillsV4.find(s=>s.name===r.skill)?.id)}}
case 'link':{const s=skillsV4.find(s=>s.id===id)||skillsV4[0];return{title:'关联目标与模块',body:`${obj('link',s.name,'复用已有技能，并保留执行记录的原关联。')}<h4>选择一个模块</h4><section class="child-list glass">${vRow('nodes','问题与方案','完成作品集项目',s.module==='问题与方案'?'当前关联':'','associate:discovery')}${vRow('doc','表达与验证','完成作品集项目',s.module==='表达与验证'?'当前关联':'','associate:delivery')}</section><p class="notice">确认后修改当前演示中的关联；不会复制技能或其历史记录。</p>`}}
case 'calendar':return calendarV4();case 'calendar-list':return calendarList();case 'calendar-default':return{title:'默认写入日历',body:`<p class="notice">从有写入权限的日历中选择；此处为隔离示例。</p><section class="child-list glass">${calChoices.map(n=>`<button class="toggle-row" data-v4="cal-default:${n}"><div><strong>${n}</strong><p>示例日历</p></div><span class="checkcircle ${calDefault===n?'checked':''}">${calDefault===n?icon('check'):''}</span></button>`).join('')}</section><p class="notice">选择默认日历不代表已经写入。每次新增或修改仍需明确确认。</p>`,footer:vPrimary('保留默认日历','back')};
case 'calendar-request':return{title:'设备授权',body:`${obj('calendar',calDevice+' 日历',calMode==='busy'?'查看占用需要读取已有事件。系统可能请求完整日历访问权限。':'只添加 QuestLife 计划，不读取已有事件。')}<section class="child-list glass">${vMetrics([['当前设备',calDevice],['希望使用',calMode==='busy'?'查看占用并规划':'只添加计划'],['系统授权','等待原生 App 请求'],['实际连接','本预览未接入']])}</section><p class="notice">系统授权必须由对应设备的原生 App 发起。这里不会显示伪造的系统授权弹窗，也不会把点击继续当作授权成功。</p><h4>预览连接后的界面</h4><button class="choice-tile glass" data-v4="cal-simulate">${icon('calendar')}<div><strong>载入隔离日历示例</strong><p>展示忙闲叠加与同步状态，不连接设备</p></div>${icon('chevron')}</button>`,footer:vPrimary('返回日历设置','calendar')};
case 'calendar-sync':return{title:'设备与同步',body:`${obj('cloud','日历写回与同步','QuestLife 计划、设备日历写入与跨设备同步分别确认。')}<section class="child-list glass">${vMetrics([['QuestLife 计划','本页演示'],[calDevice+' 授权',calRequest?'等待系统结果':'尚未请求'],['设备日历写入','未执行'],['其他设备同步','尚未验证']])}</section><div class="child-list glass">${vRow('calendar','检查日历范围',selectedCalendars.join('、'),'','calendar-list')}${vRow('shield','撤销与冲突','后续修改发生时重新审阅','','calendar-conflicts')}</div><p class="notice">设备写入成功不等于其他设备已同步。失败时保留计划与错误，再选择重试。</p>`};
case 'calendar-conflicts':return{title:'写入与冲突',body:`${obj('shield','每一步都有确认','保留计划，明确下一步。')}<div class="child-list glass">${vMetrics([['待写入','QuestLife 计划已保留'],['写入失败','保留修改，允许重试'],['版本变化','停止覆盖，重新审阅差异'],['撤销冲突','不覆盖之后的修改']])}</div><p class="notice">本原型只展示状态设计，没有读写系统日历。</p>`};
case 'smart-preferences':return{title:'调配偏好',body:`<div class="form-group glass"><label class="field">可移动计划<select><option>阅读与笔记</option></select></label><label class="field">偏好开始时间<input type="time" value="14:30"></label></div><section class="child-list glass">${toggle('保留原型设计','09:30–10:15，不自动移动',true,'plan-protect')}${toggle('保留散步','17:30–18:00，不自动移动',true,'plan-protect')}${toggle('保持原时长','本轮只调整时间，不缩短任务',true,'plan-protect')}</section><p class="notice">本轮示例按这些条件展示建议。修改条件后的重新生成需接入正式调度服务。</p>`,footer:vPrimary('返回调配建议','back')};case 'smart':return smartV4();case 'smart-review':return smartReview();case 'smart-result':if(!readingMoved)return smartReview();return{title:'调整结果',body:`<div class="success-symbol">${icon('check')}</div>${obj('calendar','阅读时间已调整','本页演示计划 · 14:30–15:00')}<section class="child-list glass">${vMetrics([['原时间','14:00–14:30'],['当前时间','14:30–15:00'],['计划时长','30 分钟，未改变'],['外部日历','未写入']])}</section><p class="notice">可以撤销这次计划修改；已经发生的实际执行不会被撤销。</p>${flowError?`<p class="error-inline">${flowError}</p>`:''}`,footer:V4('返回日程','root','sub-secondary')+vPrimary('撤销这次调整','smart-undo')};
case 'plan':{const s=skillsV4.find(s=>s.id===id)||skillsV4[0],times=id==='reading'?(readingMoved?'14:30–15:00':'14:00–14:30'):id==='walk'?'17:30–18:00':'09:30–10:15';return{title:'计划详情',action:V4(icon('edit'),'plan-edit:'+id,'glass'),body:`${obj(s.ic,s.name,'2026.11.05 · 周四')}<section class="child-list glass">${vMetrics([['计划时间',times],['计划时长',id==='prototype'?'45 分钟':'30 分钟'],['调整方式',id==='reading'?'可以移动':'保持原安排'],['实际执行','尚未记录']])}</section><div class="child-list glass">${vRow('target','关联目标',s.target,s.module,'skill:'+id)}${vRow('calendar','设备日历','尚未写入，需要单独确认','','plan-calendar:'+id)}</div>`,footer:V4('查看智能调配','smart','sub-secondary')+vPrimary('记录实际执行','capture:'+id)}}
case 'plan-calendar':return{title:'写入设备日历',body:`${obj('calendar',skillsV4.find(s=>s.id===id)?.name||'计划','选择设备与目标日历，再确认写入。')}<section class="child-list glass">${vMetrics([['设备',calDevice],['目标日历',calDefault],['原生授权','尚未确认'],['写入状态','未执行']])}</section><p class="notice">先在原生 App 完成授权，写入成功后再显示系统事件标识与设备同步状态。</p>`,footer:vPrimary('管理原生日历','calendar')};
case 'plan-edit':return{title:'编辑计划',body:`<div class="form-group glass"><label class="field">事项<input id="plan-name" value="${id==='reading'?'阅读与笔记':id==='walk'?'散步':'原型设计'}"></label><label class="field">日期<input type="date" value="2026-11-05"></label><div class="field-pair"><label class="field">开始<input type="time" value="${id==='reading'?(readingMoved?'14:30':'14:00'):id==='walk'?'17:30':'09:30'}"></label><label class="field">结束<input type="time" value="${id==='reading'?(readingMoved?'15:00':'14:30'):id==='walk'?'18:00':'10:15'}"></label></div></div><section class="child-list glass">${toggle('保护这个时间','智能调配时保持原安排',id!=='reading','plan-protect')}</section><p class="notice">这页展示计划编辑方式；修改前需检查日期、时长和冲突。</p>`,footer:vPrimary('审阅时间变化','plan-edit-review')};
case 'state':return{title:'更新状态',body:`${obj('filter','现在的状态','按当下感受填写；未选择的项目保持未记录。')}<section class="definition glass"><p>你现在的精力如何？</p><div class="state-buttons">${[1,2,3,4,5].map(n=>V4(n,'state-select:'+n,stateDraft===n?'selected':'')).join('')}</div><p style="display:flex;justify-content:space-between;font-size:9px;margin-top:9px"><span>偏低</span><span>充足</span></p></section><p class="notice">主观状态仅代表这一次自评，不自动解释为健康或能力结论。</p>`,footer:vPrimary('保留这次状态','state-save')};
case 'skill-new':case 'skill-edit':return{title:base==='skill-new'?'创建技能':'编辑技能',body:`<div class="form-group glass"><label class="field">技能名称<input id="skill-name" value="${base==='skill-edit'?skillsV4.find(s=>s.id===id)?.name||'':''}" placeholder="你想练习或持续做的事"></label><label class="field">技能定义<textarea id="skill-definition" placeholder="描述实际可以执行的内容">${base==='skill-edit'?skillsV4.find(s=>s.id===id)?.definition||'':''}</textarea></label><label class="field">分类<select id="skill-category">${['设计与表达','研究与理解','日常与健康'].map(c=>`<option>${c}</option>`).join('')}</select></label></div><p class="notice">创建技能不会自动产生执行记录或能力等级。</p>`,footer:vPrimary('保留技能','skill-save:'+ (id||'new'))};
case 'goal-edit':return{title:'编辑目标',body:`<div class="form-group glass"><label class="field">目标名称<input value="完成作品集项目"></label><label class="field">想达成的结果<textarea>把一个问题，做成可讲清楚的方案。</textarea></label></div><div class="child-list glass">${vRow('check','完成条件','2 项条件，尚待确认','','goal-conditions')}</div>`,footer:vPrimary('返回目标','back')};
case 'account':return{title:'账户',body:`${obj('user','连接你的账户','在不同设备继续使用自己的目标与记录。')}<div class="form-group glass"><label class="field">电子邮箱<input type="email" id="account-email" placeholder="name@example.com" autocomplete="off"></label></div><p class="notice">本预览不提交邮箱或发起登录。</p><section class="child-list glass">${vMetrics([['账户身份','尚未登录'],['记录同步','未连接'],['健康上传同意','未启用']])}</section>`,footer:vPrimary('查看登录后的同步设计','sync-page')};
case 'sync-page':return{title:'账户同步',body:`${obj('cloud','同步状态','账户、记录与健康数据分别确认。')}<section class="child-list glass">${vMetrics([['账户','尚未连接'],['最后成功同步','尚未确认'],['本地待同步','未读取'],['健康云同步','未启用']])}</section><div class="child-list glass">${vRow('heart','健康云同步','单独说明范围并获得同意','','health-cloud')}${vRow('calendar','设备日历','每台设备分别授权','','calendar')}${vRow('shield','隐私与数据','管理导出与删除范围','','privacy')}</div>`};
case 'notifications':return{title:'通知与提醒',body:`${obj('bell','提醒偏好','先选择需要提醒的内容，再由设备请求通知权限。')}<section class="child-list glass">${toggle('计划开始前提醒','默认提前 10 分钟',notifyPrefs.plan,'notify-plan')}${toggle('晚间回顾','20:30，回看实际记录',notifyPrefs.review,'notify-review')}</section><section class="child-list glass">${vMetrics([['系统通知权限','尚未核验'],['已创建系统提醒','未创建']])}</section><p class="notice">本预览只保留界面选择，不创建真实通知或提醒。</p>`};
case 'health-cloud':return{title:'健康云同步',body:`${obj('cloud','选择上传范围','设备读取授权与健康云上传同意分别处理。')}<section class="child-list glass">${toggle('健康云同步','尚未启用；需明确同意上传范围',false,'health-cloud-info')}</section><h4>准备上传的类型</h4><section class="child-list glass">${vMetrics([['步数','待选择'],['睡眠','待选择'],['心率','待选择']])}</section><p class="notice">关闭后停止后续上传；此前的云端记录需要单独管理。本预览不上传健康数据。</p>`,footer:vPrimary('查看设备读取权限','native-health')};
case 'privacy':return{title:'隐私与数据控制',body:`${obj('shield','管理自己的记录','先明确范围，再选择导出或删除。')}<section class="child-list glass">${vRow('download','导出记录','选择时间、类型与格式','','export')}${vRow('doc','本机记录','查看本机保存范围','','privacy-local')}${vRow('cloud','云端记录','独立管理，不随停用同步删除','','privacy-cloud')}${vRow('user','账户删除','单独确认账户与记录影响','','privacy-account')}</section>`};
case 'export':return{title:'导出记录',body:`<div class="form-group glass"><label class="field">时间范围<select><option>全部时间</option><option>最近 30 天</option></select></label><label class="field">记录类型<select><option>手动执行记录</option><option>全部可导出记录</option></select></label><label class="field">文件格式<select><option>CSV</option><option>JSON</option></select></label></div><section class="child-list glass">${vMetrics([['当前示例',recs().length+' 条手动记录'],['健康与云端记录','未连接，不包含']])}</section><p class="notice">此原型可导出当前隔离示例的 CSV，不读取本机真实记录。</p>`,footer:vPrimary('下载示例 CSV','export-demo')};
case 'appearance':return{title:'外观',body:`<div class="skill-tiles">${['跟随系统','浅色','深色'].map((t,i)=>`<button class="skill-tile glass" data-v4="theme-info"><div style="height:80px;border-radius:12px;background:${i===2?'#20364a':'linear-gradient(140deg,#f9fdff,#cadae8)'};box-shadow:inset 0 1px #ffffff80;margin-bottom:13px"></div><strong>${t}</strong><p>${i===0?'当前偏好':'主题选项'}</p></button>`).join('')}</div><p class="notice">本轮制作浅色玻璃完整稿；深色需单独检查对比与材质。</p>`};
case 'legacy':return{title:legacyCache[id]?.title||'详情',body:`<div class="sheet-content">${legacyCache[id]?.body||''}</div>`};
default:return{title:'详情',body:`<section class="definition glass"><p>选择要查看的记录或设置。</p></section>`};}}
const legacyCache={};let legacyId=0;
function promoteSheet(phone){const wrap=phone.querySelector('.sheet-wrap');if(!wrap)return;const sh=wrap.querySelector('.sheet'),title=sh.querySelector('h3').textContent;const clone=sh.cloneNode(true);clone.querySelector('.grabber')?.remove();clone.querySelector('.sheet-header')?.remove();const id=String(++legacyId);legacyCache[id]={title,body:clone.innerHTML};wrap.remove();navigateV4(phone.id,'legacy:'+id)}
const baseRenderV4=render,baseTodayV4=today,baseActionV4=action;
today=function(){const latest=recs()[0];return `${status()}<div class="screen-content"><div class="today-date">11 月 5 日 · 周四 · 上午<span>今日信号待补</span></div><button class="capture glass" data-v4="capture">${icon('spark')}<span>记一句话：做了什么 / 现在状态…</span><i>${icon('arrow')}</i></button>${latest?`<button class="recent-capture" data-v4="record:${latest.id}"><div><small>最近记录</small><p>${esc(latest.skill)} · ${latest.minutes} 分钟</p><time>${latest.date.slice(5).replace('-','.')} · ${latest.time}</time></div>${icon('arrow')}</button>`:`<button class="recent-capture" data-v4="capture"><div><small>最近记录</small><p>还没有记录，先留下一条实际发生的事。</p></div>${icon('arrow')}</button>`}<h3 class="today-judgement">先用保守启动，<br>顺便补一条状态或睡眠信号。</h3><button class="today-command" data-v4="${scenario==='first'?'capture':'plan:prototype'}"><div><strong>${scenario==='first'?'现在建议：记录一个小行动':'现在建议：原型设计'}</strong><p>${scenario==='first'?'留下一条实际发生的事，<br>再把它关联到你想继续的方向。':'09:30 开始，先做今天这一个明确行动。<br>保留原计划，做完再记下实际执行。'}</p></div>${icon('arrow')}</button><button class="after-record" data-v4="capture:prototype">${icon('plus')}做完后记录</button><section class="today-state"><div><small>当前状态</small><strong>${localStatus?'精力 '+localStatus+' / 5':'未记录'}</strong></div><button data-v4="state">${icon('filter')}更新状态</button></section><section class="today-plan"><div class="today-plan-heading">${icon('calendar')}今日计划 · ${scenario==='first'?0:3} 项<button data-v4="today-schedule">查看日程${icon('chevron')}</button></div>${scenario==='first'?'<p class="notice">尚无计划，可以先安排一个小行动。</p>':[['prototype','原型设计','09:30–10:15'],['reading','阅读与笔记',readingMoved?'14:30–15:00':'14:00–14:30'],['walk','散步','17:30–18:00']].map(([id,n,t])=>vRow('clock',n,t,'','plan:'+id)).join('')}</section></div>${nav(0)}`};
render=function(){baseRenderV4();document.querySelectorAll('.board-title span').forEach((s,i)=>s.textContent=['本轮补齐 · 保留业务顺序','目标 / 模块 / 技能 / 执行','智能调配 / 原生日历','A0 继承 · 数据已核对','设备 / 同步 / 隐私'][i]);const sc=document.querySelector('#schedule .weekstrip');if(sc){const div=document.createElement('div');div.className='schedule-tools';div.innerHTML=`<button class="glass smart-button" data-v4="smart">${icon('spark')}智能调配 <span>${readingMoved?'已调整':'1 项待审阅'}</span></button><button class="glass" data-v4="calendar">${icon('calendar')}原生日历 <span>${calSimulated?'示例':'未连接'}</span></button>`;sc.before(div);document.querySelectorAll('#schedule .timeline .event,#schedule .timeline .time-gap,#schedule .timeline .nowline').forEach(el=>{el.style.top=(parseFloat(el.style.top)*29/32)+'px';if(el.style.height)el.style.height=(parseFloat(el.style.height)*29/32)+'px'});if(calSimulated){const ev=document.createElement('button');ev.className='event external';ev.style.cssText='top:174px;height:14.5px;left:7px;right:50%;background:#e3e7ecb3;border:1px dashed #91a5b7;color:#657f96';ev.dataset.v4='calendar-sync';ev.innerHTML='<strong>会议 · 日历示例</strong>';document.querySelector('#schedule .timeline').append(ev)}}const tree=document.querySelector('#goals .tree');if(tree){tree.innerHTML=['问题与方案','表达与验证'].map((name,i)=>{const ss=skillsV4.filter(s=>s.module===name&&s.target==='完成作品集项目');return `<section class="module"><div class="module-head" data-v4="module:${i===0?'discovery':'delivery'}"><b>${name}</b><small>${ss.length} 个技能</small></div>${ss.map(s=>`<button class="skill-line" data-v4="skill:${s.id}">${icon(s.ic)}<div><strong>${esc(s.name)}</strong><p>${s.id==='prototype'?'下一次计划 · 今天 09:30':esc(s.definition.slice(0,17))}</p></div><span class="mini-count">${recs(s.name).length?recs(s.name).length+' 次':'—'}<small>${recs(s.name).length?recs(s.name).reduce((n,r)=>n+r.minutes,0)+' 分钟':'暂无执行'}</small></span></button>`).join('')}</section>`}).join('');const total=recs().filter(r=>skillsV4.find(s=>s.name===r.skill)?.target==='完成作品集项目').reduce((n,r)=>n+r.minutes,0);document.querySelector('#goals .goal-footer span').innerHTML=icon('clock')+'已记录 '+total+' 分钟';} const plist=document.querySelector('#personal .profile-list');if(plist)plist.insertAdjacentHTML('beforeend',vRow('calendar','原生日历','设备授权、占用与写回','管理','calendar'));document.querySelectorAll('.goal-main-top>div').forEach(el=>{el.dataset.v4='goal'});document.querySelectorAll('.module-head').forEach((el,i)=>el.dataset.v4='module:'+(i===0?'discovery':'delivery'));for(const k of KEYS)paintV4(k);applyRenamesV4(document.querySelector('#boards'))};
action=function(phone,a){if(!phone)return;const map={'skill-new':'skill-new','skill-library':'library','goal-detail':'goal','record-execution':'capture','actual-records':'records','proposal':'smart','undo-review':'smart-result','plan-prototype':'plan:prototype','plan-reading':'plan:reading','plan-walk':'plan:walk','skill-interview':'skill:interview','skill-prototype':'skill:prototype','skill-present':'skill:present','skill-test':'skill:test','account':'account','sync-details':'sync-page','notifications':'notifications','privacy':'privacy','appearance':'appearance','health-cloud':'health-cloud','export-info':'export','new-plan':'plan-edit:new'};if(a==='close'){backV4(phone.id);return}if(a==='about'){handleV4(phone,'about');return}if(map[a]&&!(scenario==='error'&&['goals','analysis'].includes(phone.id))){navigateV4(phone.id,map[a]);return}const countBefore=extraGoals.length;baseActionV4(phone,a);if(a==='save-goal'&&extraGoals.length>countBefore){v4Stacks[phone.id]=[];render();return}promoteSheet(phone)};
function handleV4(phone,a){const key=phone.id,[base,id]=a.split(':');flowError='';switch(base){case 'back':backV4(key);return;case 'root':v4Stacks[key]=[];render();return;case 'filter':v4Filter=id;paintV4(key);return;case 'device':calDevice=id;calRequest=false;paintV4(key);return;case 'cal-mode':calMode=id;paintV4(key);return;case 'cal-select':selectedCalendars=selectedCalendars.includes(id)?selectedCalendars.filter(n=>n!==id):[...selectedCalendars,id];paintV4(key);return;case 'cal-selection-save':backV4(key);toast(phone,'已保留本页的日历范围示例。');return;case 'cal-default':calDefault=id;paintV4(key);return;case 'cal-request':calRequest=true;navigateV4(key,'calendar-request');return;case 'cal-simulate':calSimulated=true;v4Stacks[key]=[];render();navigateV4(key,'calendar-sync');return;case 'cal-busy-info':sheet(phone,'忙闲范围','<p>可以仅使用起止时间做占用检查。系统读取仍需要相应日历访问权限；这个选项不代表系统提供单独的只读权限。</p>');promoteSheet(phone);return;
case 'capture-review':{const get=id=>phone.querySelector('#'+id).value;recordForm={skill:get('v-skill'),note:get('v-note').trim(),minutes:get('v-minutes'),date:get('v-date'),time:get('v-time')};if(!recordForm.note||!Number.isFinite(+recordForm.minutes)||+recordForm.minutes<=0||!recordForm.date||!recordForm.time){flowError='请补全实际内容、日期、时间和大于零的分钟数。';paintV4(key);return}navigateV4(key,'capture-review');return}
case 'capture-save':if(edgecase==='save-error'){flowError='保存未确认，草稿已保留，执行次数没有增加。';paintV4(key);return}addedRecords.unshift({...recordForm,minutes:+recordForm.minutes,id:'local-'+(addedRecords.length+1)});recordForm.note='';v4Stacks[key]=[];render();toast(document.getElementById(key),'已保留本页演示记录；刷新后重置。');return;
case 'state-select':stateDraft=+id;paintV4(key);return;case 'state-save':if(!stateDraft){toast(phone,'请选择当下的自评，或返回保持未记录。');return}localStatus=stateDraft;v4Stacks[key]=[];render();return;
case 'associate':{const route=v4Stacks[key].at(-1),sid=route?.split(':')[1]||'prototype',s=skillsV4.find(s=>s.id===sid);if(s)s.module=id==='discovery'?'问题与方案':'表达与验证';toast(phone,'已在本页会话关联到'+(id==='discovery'?'问题与方案':'表达与验证'));backV4(key);render();return}
case 'skill-save':{const name=phone.querySelector('#skill-name').value.trim(),def=phone.querySelector('#skill-definition').value.trim(),cat=phone.querySelector('#skill-category').value;if(!name){toast(phone,'先填写技能名称。');return}if(id==='new')skillsV4.push({id:'custom-'+skillsV4.length,name,definition:def||'尚未补充定义',category:cat,module:'待关联',target:'待关联目标',ic:'folder'});else{const s=skillsV4.find(s=>s.id===id);if(s){s.name=name;s.definition=def;s.category=cat}}v4Filter='全部';v4Stacks[key]=['library'];render();return}
case 'skill-plan':if(['prototype','reading','walk'].includes(id))navigateV4(key,'plan:'+id);else{sheet(phone,'相关计划','<p>这个技能目前没有计划。可以选择日期与时间，或先保留为待安排。</p>'+vPrimary('安排一次','plan-edit:'+id));promoteSheet(phone)}return;
case 'smart-review':if(readingMoved)navigateV4(key,'smart-result');else navigateV4(key,'smart-review');return;
case 'smart-apply':if(edgecase==='stale'){flowError='建议已过期。安排在审阅后发生变化，请重新获取并核对差异；未应用。';paintV4(key);return}readingMoved=true;v4Stacks[key]=['smart-result'];render();return;
case 'smart-undo':if(edgecase==='undo-conflict'){flowError='当前安排有后续修改，暂时无法撤销。请重新审阅，未覆盖当前版本。';paintV4(key);return}readingMoved=false;v4Stacks[key]=[];render();toast(document.getElementById(key),'已恢复原阅读时间 14:00–14:30。');return;
case 'today-schedule':if(document.body.classList.contains('single')){history.replaceState(null,'','?screen=schedule');document.querySelectorAll('.board').forEach(b=>b.classList.toggle('selected',b.id==='board-schedule'))}else document.querySelector('#board-schedule').scrollIntoView({behavior:'smooth',inline:'center',block:'nearest'});return;
case 'record-filters':sheet(phone,'筛选记录',skillsV4.map(s=>vRow(s.ic,s.name,'',recs(s.name).length+' 条','records:'+s.name)).join(''));promoteSheet(phone);return;
case 'goal-conditions':baseActionV4(phone,'goal-conditions');promoteSheet(phone);return;
case 'plan-edit-review':sheet(phone,'计划修改待确认','<p>此页面展示编辑与审阅结构。正式保存需同时检查结束晚于开始、时间冲突与最新版本。</p><p>本轮可以通过智能调配流程完整体验一项可应用、可撤销的时间修改。</p>'+vPrimary('进入智能调配','smart'));promoteSheet(phone);return;
case 'plan-protect':toast(phone,'这个示例保留固定事项，智能调配只移动阅读计划。');return;
case 'native-health':baseActionV4(phone,'native-health');promoteSheet(phone);return;
case 'health-cloud-info':baseActionV4(phone,'health-cloud');promoteSheet(phone);return;
case 'privacy-local':case 'privacy-cloud':case 'privacy-account':sheet(phone,{'privacy-local':'本机记录','privacy-cloud':'云端记录','privacy-account':'账户删除'}[base],'<p>确认范围后才能执行删除。关闭同步不会删除云端记录；设备本机副本与账户数据需要分别处理。</p><p>本设计预览不执行真实删除。</p>');promoteSheet(phone);return;
case 'export-demo':{const rows=[['skill','date','time','minutes','note'],...recs().map(r=>[r.skill,r.date,r.time,r.minutes,r.note])],csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='QuestLife-synthetic-records.csv';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast(phone,'已导出当前隔离示例。');return}
case 'notify-plan':case 'notify-review':{const el=phone.querySelector(`[data-v4="${a}"] .toggle`);const pref=base==='notify-plan'?'plan':'review';notifyPrefs[pref]=!notifyPrefs[pref];el.classList.toggle('on',notifyPrefs[pref]);toast(phone,'已保留本页提醒偏好；未创建系统提醒。');return}
case 'theme-info':toast(phone,'本轮为浅色玻璃稿，当前没有切换到深色。');return;
case 'about':sheet(phone,'关于本轮设计','<p>五个主页及可进入的子页面。Today 依据既有业务顺序补齐，原始 T0 仍未恢复。本轮加强玻璃材质，去除重复的页首大标题。</p><p>数据与交互均为隔离示例；没有连接真实账户、生产、HealthKit 或系统日历。</p>');promoteSheet(phone);return;
default:navigateV4(key,a)} }
document.addEventListener('click',e=>{const b=e.target.closest('[data-v4]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const phone=b.closest('.phone');if(phone)handleV4(phone,b.dataset.v4)},true);
window.addEventListener('popstate',e=>{v4Stacks=e.state?.v4Stacks||initialV4Stacks();for(const k of KEYS)paintV4(k);const s=new URLSearchParams(location.search).get('screen');if(s&&document.body.classList.contains('single'))document.querySelectorAll('.board').forEach(b=>b.classList.toggle('selected',b.id==='board-'+s))});
document.querySelector('#scenario').addEventListener('change',()=>{v4Stacks=initialV4Stacks();addedRecords=[];localStatus=null;stateDraft=null;flowError='';calSimulated=false;render()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const p=document.activeElement?.closest('.phone')||document.querySelector('.board.selected .phone');if(p&&v4Stacks[p.id]?.length){e.stopImmediatePropagation();backV4(p.id)}}},true);
const q4=new URLSearchParams(location.search);if(q4.get('view')&&KEYS.includes(q4.get('screen'))){v4Stacks[q4.get('screen')]=[q4.get('view')];if(q4.get('view').startsWith('capture:')){const s=skillsV4.find(s=>s.id===q4.get('view').split(':')[1]);if(s)recordForm.skill=s.name}}
render();
